SELECT end_user_id FROM public.agent_runtime_session_owners
 WHERE tenant_id=#{owner.sessionRef.tenantId.value} AND session_id=#{owner.sessionRef.sessionId}
   AND target_kind=#{owner.target.kind} AND target_id=#{owner.target.id} AND end_user_id=#{owner.requireUser.value}
 FOR NO KEY UPDATE

SELECT 
  FROM public.agent_runtime_session_events WHERE 
   AND event_type='agent.model-reasoning' AND session_sequence>#{after}
   AND session_sequence<=#{through}
 ORDER BY session_sequence LIMIT #{limit} FOR UPDATE SKIP LOCKED

SELECT event_id,session_sequence FROM public.agent_runtime_session_events WHERE 
   AND event_type='agent.model-reasoning' AND session_sequence>#{after}
 ORDER BY session_sequence LIMIT #{limit}
